import { useState, ReactNode, useId, FormEvent } from "react";

// ============================================================
// 1. المكونات المساعدة (Helper Components)
// ============================================================

interface TextFieldProps {
  label: string;
  value: string;
  onChange: (v: string) => void;
  type?: string;
  placeholder?: string;
  required?: boolean;
  multiline?: boolean;
  rows?: number;
  min?: string | number;
  max?: string | number;
  className?: string;
  error?: string;
}

export function TextField({
  label,
  value,
  onChange,
  type = "text",
  placeholder,
  required,
  multiline = false,
  rows = 3,
  min,
  max,
  className = "",
  error,
}: TextFieldProps) {
  const id = useId();
  const baseClass =
    "w-full px-4 py-2.5 border border-[var(--border)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[var(--brand-green)]/30 focus:border-[var(--brand-green)] bg-[var(--card)] transition-colors " +
    className;

  return (
    <div className="mb-4">
      <label
        htmlFor={id}
        className="block mb-1.5 text-[var(--foreground)]"
        style={{ fontSize: "0.82rem", fontWeight: 600 }}
      >
        {label} {required && <span className="text-red-500">*</span>}
      </label>
      {multiline ? (
        <textarea
          id={id}
          rows={rows}
          value={value}
          onChange={(e) => onChange(e.target.value)}
          placeholder={placeholder}
          required={required}
          aria-required={required}
          aria-invalid={!!error}
          className={baseClass}
          style={{ fontSize: "0.85rem", resize: "vertical" }}
        />
      ) : (
        <input
          id={id}
          type={type}
          value={value}
          onChange={(e) => onChange(e.target.value)}
          placeholder={placeholder}
          required={required}
          min={min}
          max={max}
          aria-required={required}
          aria-invalid={!!error}
          className={baseClass}
          style={{ fontSize: "0.85rem" }}
        />
      )}
      {error && <p className="text-sm text-red-600 mt-1">{error}</p>}
    </div>
  );
}

interface SelectFieldProps {
  label: string;
  value: string;
  onChange: (v: string) => void;
  options: { value: string; label: string }[];
  required?: boolean;
  className?: string;
}

export function SelectField({
  label,
  value,
  onChange,
  options,
  required,
  className = "",
}: SelectFieldProps) {
  const id = useId();
  return (
    <div className="mb-4">
      <label
        htmlFor={id}
        className="block mb-1.5 text-[var(--foreground)]"
        style={{ fontSize: "0.82rem", fontWeight: 600 }}
      >
        {label} {required && <span className="text-red-500">*</span>}
      </label>
      <select
        id={id}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        required={required}
        aria-required={required}
        className={`w-full px-4 py-2.5 border border-[var(--border)] rounded-lg focus:outline-none focus:ring-2 focus:ring-[var(--brand-green)]/30 bg-[var(--card)] transition-colors ${className}`}
        style={{ fontSize: "0.85rem" }}
      >
        <option value="">اختر...</option>
        {options.map((opt) => (
          <option key={opt.value} value={opt.value}>
            {opt.label}
          </option>
        ))}
      </select>
    </div>
  );
}

interface CheckboxFieldProps {
  label: string;
  checked: boolean;
  onChange: (checked: boolean) => void;
  className?: string;
}

export function CheckboxField({ label, checked, onChange, className = "" }: CheckboxFieldProps) {
  return (
    <label
      className={`flex items-center gap-2 text-[var(--foreground)] ${className}`}
      style={{ fontSize: "0.82rem", fontWeight: 500 }}
    >
      <input
        type="checkbox"
        checked={checked}
        onChange={(e) => onChange(e.target.checked)}
        className="rounded text-[var(--brand-green)] focus:ring-[var(--brand-green)] border-[var(--border)] w-4 h-4"
      />
      {label}
    </label>
  );
}

interface FormActionsProps {
  onSave: (e: React.FormEvent) => void;
  onCancel: () => void;
  submitLabel?: string;
  cancelLabel?: string;
}

export function FormActions({
  onSave,
  onCancel,
  submitLabel = "حفظ",
  cancelLabel = "إلغاء",
}: FormActionsProps) {
  return (
    <div className="flex gap-3 pt-4 border-t border-[var(--border)] mt-6">
      <button
        type="submit"
        onClick={onSave}
        className="flex-1 py-2.5 bg-[var(--brand-green)] text-white rounded-lg hover:bg-[var(--brand-green-light)] transition-colors"
        style={{ fontSize: "0.85rem", fontWeight: 600 }}
      >
        {submitLabel}
      </button>
      <button
        type="button"
        onClick={onCancel}
        className="flex-1 py-2.5 border border-[var(--border)] rounded-lg hover:bg-[var(--muted)] transition-colors"
        style={{ fontSize: "0.85rem" }}
      >
        {cancelLabel}
      </button>
    </div>
  );
}

interface FormModalProps {
  isOpen: boolean;
  onClose: () => void;
  title: string;
  children: ReactNode;
  size?: "sm" | "md" | "lg";
}

export function FormModal({ isOpen, onClose, title, children, size = "md" }: FormModalProps) {
  if (!isOpen) return null;
  const widthMap = { sm: "max-w-md", md: "max-w-lg", lg: "max-w-2xl" };
  return (
    <div
      className="fixed inset-0 z-[200] flex items-center justify-center p-4"
      role="dialog"
      aria-modal="true"
      aria-labelledby="form-modal-title"
    >
      <button
        type="button"
        aria-label="إغلاق"
        className="absolute inset-0 bg-black/50 backdrop-blur-sm"
        onClick={onClose}
        onKeyDown={(e) => {
          if (e.key === "Escape") onClose();
        }}
      />
      <div
        className={`relative bg-[var(--card)] rounded-2xl p-6 w-full ${widthMap[size]} shadow-2xl max-h-[90vh] overflow-y-auto`}
        style={{ direction: "rtl" }}
      >
        <div className="flex items-center justify-between mb-5 sticky top-0 bg-[var(--card)] pb-3 border-b border-[var(--border)] z-10">
          <h3 id="form-modal-title" style={{ fontWeight: 700, fontSize: "1rem" }}>
            {title}
          </h3>
          <button
            onClick={onClose}
            aria-label="إغلاق"
            className="p-1.5 rounded-lg hover:bg-[var(--muted)] transition-colors"
          >
            ✕
          </button>
        </div>
        {children}
      </div>
    </div>
  );
}

