      { id: "success", label: "قصص النجاح", icon: Award },
      { id: "impact", label: "الأثر المجتمعي", icon: Target },
      { id: "impact-center", label: "مركز الأثر", icon: BarChart3 },
      { id: "impact-engine", label: "محرك الأثر", icon: Sparkles, badge: "جديد" },
