        <p className="mt-1 font-bold text-[var(--foreground)]">{amount >= 25000 ? 'حفر بئر مياه نقية' : amount >= 10000 ? 'كفالة يتيم شهري' : amount >= 5000 ? 'كسوة شتوية' : 'سلة غذائية'}</p>
