            { icon: Clock, title: 'سرعة الاستجابة', desc: 'نرد خلال ٢٤-٤٨ ساعة', color: 'bg-blue-500' },
            { icon: Shield, title: 'خصوصية تامة', desc: 'بياناتك محمية ولن تُشارك', color: 'bg-[var(--brand-green)]' },
