              ماذا يقول شركاؤنا في برنامج كبار المانحين
            </p>
          </motion.div>

          <motion.div
            variants={staggerContainer}
            initial="initial"
            whileInView="visible"
            viewport={viewportOnce}
            className="grid gap-8 md:grid-cols-3"
          >
            {TESTIMONIALS.map((testimonial) => (
              <motion.div
                key={testimonial.id}
                variants={scrollFadeUp}
                className="relative overflow-hidden rounded-3xl border border-[var(--border)] bg-[var(--card)] p-8 shadow-md transition-all duration-500 hover:-translate-y-2 hover:shadow-xl"
              >
                <Quote className="absolute left-4 top-4 h-12 w-12 text-[var(--brand-green)]/10" />
                <div className="relative z-10">
                  <p className="mb-6 text-sm leading-relaxed text-[var(--foreground)]">
                    &ldquo;{testimonial.quote}&rdquo;
                  </p>
                  <div className="flex items-center gap-3 border-t border-[var(--border)] pt-4">
                    <div className="grid h-10 w-10 place-items-center rounded-full bg-[var(--brand-green)] text-sm font-bold text-white">
                      {testimonial.avatar}
                    </div>
                    <div>
                      <div className="text-sm font-bold text-[var(--foreground)]">
                        {testimonial.name}
                      </div>
                      <div className="flex items-center gap-2 text-xs text-[var(--muted-foreground)]">
                        <span className="rounded-full bg-[var(--brand-green-pale)] px-2 py-0.5 text-[var(--brand-green)]">
                          {testimonial.tier}
                        </span>
                        <span>{testimonial.yearsActive} سنوات</span>
                      </div>
                    </div>
                  </div>
                </div>
              </motion.div>
            ))}
          </motion.div>
        </div>
      </section>

      {/* ═══════ Application Form ═══════ */}
      <section className="bg-[var(--secondary)] py-16">
        <div className="mx-auto max-w-4xl px-4 sm:px-6 lg:px-8">
          <motion.div
            initial={{ opacity: 0, y: 30 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={viewportOnce}
            className="mb-12 text-center"
          >
            <h2 className="mb-4 text-3xl font-bold md:text-5xl">
              انضم <span className="text-[var(--brand-green)]">للبرنامج</span>
            </h2>
            <p className="mx-auto max-w-2xl text-[var(--muted-foreground)]">
              سجّل الآن وابدأ رحلتك مع برنامج كبار المانحين
            </p>
          </motion.div>

          <motion.div
            initial={{ opacity: 0, y: 30 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={viewportOnce}
            className="overflow-hidden rounded-3xl border border-[var(--border)] bg-[var(--card)] shadow-xl"
          >
            <div className="bg-gradient-to-l from-[var(--brand-green)] to-[var(--brand-green-light)] p-6">
              <h3 className="flex items-center gap-2 text-lg font-bold text-white">
                <Crown className="h-5 w-5" />
                نموذج الانضمام
              </h3>
            </div>

            <div className="space-y-6 p-5 sm:p-6">
              <div className="grid gap-6 md:grid-cols-2">
                <div>
                  <label className="mb-2 block text-sm font-bold text-[var(--foreground)]">
                    الاسم الكامل *
                  </label>
                  <input
                    type="text"
                    name="name"
                    value={formData.name}
                    onChange={handleInputChange}
                    placeholder="أدخل اسمك الكامل"
                    className="w-full rounded-xl border border-[var(--border)] bg-[var(--input-background)] px-4 py-3 text-sm text-[var(--foreground)] placeholder:text-[var(--muted-foreground)] focus:border-[var(--brand-green)] focus:outline-none focus:ring-2 focus:ring-[var(--brand-green)]/20"
                  />
                </div>
                <div>
                  <label className="mb-2 block text-sm font-bold text-[var(--foreground)]">
                    رقم الهاتف *
                  </label>
                  <input
                    type="tel"
                    name="phone"
                    value={formData.phone}
                    onChange={handleInputChange}
                    placeholder="77xxxxxxx"
                    className="w-full rounded-xl border border-[var(--border)] bg-[var(--input-background)] px-4 py-3 text-sm text-[var(--foreground)] placeholder:text-[var(--muted-foreground)] focus:border-[var(--brand-green)] focus:outline-none focus:ring-2 focus:ring-[var(--brand-green)]/20"
                  />
                </div>
              </div>

              <div className="grid gap-6 md:grid-cols-2">
                <div>
                  <label className="mb-2 block text-sm font-bold text-[var(--foreground)]">
                    البريد الإلكتروني
                  </label>
                  <input
                    type="email"
                    name="email"
                    value={formData.email}
                    onChange={handleInputChange}
                    placeholder="example@email.com"
                    className="w-full rounded-xl border border-[var(--border)] bg-[var(--input-background)] px-4 py-3 text-sm text-[var(--foreground)] placeholder:text-[var(--muted-foreground)] focus:border-[var(--brand-green)] focus:outline-none focus:ring-2 focus:ring-[var(--brand-green)]/20"
                  />
                </div>
                <div>
                  <label className="mb-2 block text-sm font-bold text-[var(--foreground)]">
                    المبلغ السنوي المقصود (ر.ي) *
                  </label>
                  <select
                    name="annualGiving"
                    value={formData.annualGiving}
                    onChange={handleInputChange}
                    className="w-full rounded-xl border border-[var(--border)] bg-[var(--input-background)] px-4 py-3 text-sm text-[var(--foreground)] focus:border-[var(--brand-green)] focus:outline-none focus:ring-2 focus:ring-[var(--brand-green)]/20"
                  >
                    <option value="">اختر المبلغ</option>
                    <option value="100000">١٠٠,٠٠٠+ ر.ي (الْكِمَّة)</option>
                    <option value="250000">٢٥٠,٠٠٠+ ر.ي (الْمُحَفِّص)</option>
                    <option value="500000">٥٠٠,٠٠٠+ ر.ي (الدَّوْرِيَّة)</option>
                  </select>
                </div>
              </div>

              <div>
                <label className="mb-2 block text-sm font-bold text-[var(--foreground)]">
                  المشاريع المفضلة
                </label>
                <select
                  name="preferredProjects"
                  value={formData.preferredProjects}
                  onChange={handleInputChange}
                  className="w-full rounded-xl border border-[var(--border)] bg-[var(--input-background)] px-4 py-3 text-sm text-[var(--foreground)] focus:border-[var(--brand-green)] focus:outline-none focus:ring-2 focus:ring-[var(--brand-green)]/20"
                >
                  <option value="">اختر نوع المشاريع</option>
                  <option value="water">آبار مياه</option>
                  <option value="education">تعليم</option>
                  <option value="health">رعاية صحية</option>
                  <option value="food">سلال غذائية</option>
                  <option value="shelter">إيواء</option>
                  <option value="empowerment">تمكين اقتصادي</option>
                </select>
              </div>

              <div>
                <label className="mb-2 block text-sm font-bold text-[var(--foreground)]">
                  رسالتك
                </label>
                <textarea
                  name="message"
                  value={formData.message}
                  onChange={handleInputChange}
                  rows={4}
                  placeholder="أي ملاحظات أو تفضيلات خاصة..."
                  className="w-full rounded-xl border border-[var(--border)] bg-[var(--input-background)] px-4 py-3 text-sm text-[var(--foreground)] placeholder:text-[var(--muted-foreground)] focus:border-[var(--brand-green)] focus:outline-none focus:ring-2 focus:ring-[var(--brand-green)]/20"
                />
              </div>

              <button
                onClick={() => navigate("/contact")}
                className="flex w-full items-center justify-center gap-2 rounded-xl bg-[var(--brand-green)] px-8 py-4 text-sm font-bold text-white transition-all hover:bg-[var(--brand-green-dark)] hover:shadow-lg"
              >
                <Send className="h-4 w-4" />
                انضم للبرنامج
              </button>
            </div>
          </motion.div>
        </div>
      </section>

      {/* ═══════ Impact of Major Donors ═══════ */}
      <section className="bg-gradient-to-br from-[var(--brand-green-dark)] to-[var(--brand-green)] py-16">
        <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
          <motion.div
            initial={{ opacity: 0, y: 30 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={viewportOnce}
            className="mb-12 text-center"
          >
            <h2 className="mb-4 text-3xl font-bold text-white md:text-5xl">
              أثر <span className="text-[var(--brand-gold-light)]">كبار المانحين</span>
            </h2>
            <p className="mx-auto max-w-2xl text-white/70">
              أرقام تعكس حجم الأثر الذي يصنعه كبار مانحينا في حياة المستفيدين
            </p>
          </motion.div>

          <div className="mx-auto grid max-w-4xl gap-6 sm:grid-cols-2 lg:grid-cols-4">
            {IMPACT_STATS.map((stat, i) => {
              const Icon = stat.icon;
              return (
                <motion.div
                  key={stat.label}
                  initial={{ opacity: 0, y: 20 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={viewportOnce}
                  transition={{ delay: i * 0.1 }}
                  className="rounded-2xl border border-white/10 bg-white/10 p-6 text-center backdrop-blur-sm transition-all duration-300 hover:-translate-y-1 hover:bg-white/15"
                >
                  <div className="mx-auto mb-3 flex h-12 w-12 items-center justify-center rounded-full bg-white/15">
                    <Icon className="h-6 w-6 text-[var(--brand-gold-light)]" />
                  </div>
                  <div className="text-2xl font-bold text-white">{stat.value}</div>
                  <div className="mt-1 text-xs text-white/60">{stat.label}</div>
                </motion.div>
              );
            })}
          </div>
        </div>
      </section>

      {/* ═══════ Final CTA ═══════ */}
      <section className="bg-[var(--background)] py-16">
        <div className="mx-auto max-w-4xl px-4 text-center sm:px-6 lg:px-8">
          <motion.div
            initial={{ opacity: 0, y: 30 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={viewportOnce}
          >
            <Crown className="mx-auto mb-4 h-10 w-10 text-[var(--brand-gold)]" />
            <h2 className="mb-4 text-2xl font-bold text-[var(--foreground)] md:text-4xl">
              شرف العطاء يبدأ من هنا
            </h2>
            <p className="mx-auto mb-8 max-w-xl text-lg text-[var(--muted-foreground)]">
              كن شريكاً في صنع الأثر واحصل على تجربة فريدة في متابعة أثرك
            </p>
            <div className="flex flex-wrap justify-center gap-4">
              <button
                onClick={() => navigate("/donate")}
                className="flex items-center gap-2 rounded-xl bg-[var(--brand-green)] px-8 py-4 text-lg font-bold text-white shadow-2xl transition-all hover:bg-[var(--brand-green-dark)] hover:shadow-2xl"
              >
                <Heart className="h-5 w-5" />
                تبرع الآن
              </button>
              <button
                onClick={() => navigate("/contact")}
                className="flex items-center gap-2 rounded-xl border-2 border-[var(--brand-green)]/30 px-8 py-4 text-lg font-bold text-[var(--brand-green)] transition-all hover:bg-[var(--brand-green)] hover:text-white"
              >
                <Send className="h-5 w-5" />
                تواصل معنا
              </button>
            </div>
          </motion.div>
        </div>
      </section>
    </div>
  );
}

// News Page - صفحة الأخبار
import {
  Newspaper,
  FolderOpen,
  Calendar,
  Tag,
  Search,
  TrendingUp,
  Eye,
  ArrowLeft,
  BarChart3,
} from "lucide-react";
import { motion } from "motion/react";
import { useState, useEffect, useMemo } from "react";
import { useNavigate } from "react-router-dom";

import { PageHeader } from "@/app/components/PageHeader";
import { Skeleton, CardSkeleton } from "@/app/components/Skeleton";
import { StatsGrid } from "@/app/components/StatsGrid";
import { SEED_NEWS_ITEMS, NEWS_CATEGORIES } from "@/content/website";
import { analyticsService } from "@/shared/services/analytics.service";
import { contentManager } from "@/shared/services/content-manager";
import { useSEO } from "@/utils/seoAdvanced";

function NewsLoadingSkeleton() {
  return (
    <div className="min-h-screen pt-24 pb-16 bg-[var(--background)]" style={{ direction: "rtl" }}>
      <div className="max-w-7xl mx-auto px-4 sm:px-6">
        <div className="mb-10 text-center">
          <Skeleton width="100px" height="28px" className="mx-auto mb-3" />
          <Skeleton width="300px" height="36px" className="mx-auto" />
          <Skeleton width="400px" height="20px" className="mx-auto mt-2" />
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {Array.from({ length: 6 }).map((_, i) => (
            <CardSkeleton key={`news-card-${i}`} />
          ))}
        </div>
      </div>
    </div>
  );
}

export default function NewsPage() {
  const navigate = useNavigate();
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [news, setNews] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeCategory, setActiveCategory] = useState("الكل");
  const [searchQuery, setSearchQuery] = useState("");
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const [contentSource, setContentSource] = useState<"static" | "cache" | "sanity">("static");

  useSEO({
    title: "الأخبار - رحماء بينهم",
    description: "الأخبار والفعاليات الأخيرة لـ رحماء بينهم الإنسانية",
    type: "website",
    url: "https://rbdcye.org/news",
    image: "https://rbdcye.org/og-news.png",
    keywords: ["أخبار", "فعاليات", "إغاثة", "تنمية", "تعليم", "يمن", "رحماء بينهم"],
  });

  useEffect(() => {
    let cancelled = false;

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const fallback = SEED_NEWS_ITEMS.map((n: any) => ({
      id: n.id,
      title: n.title,
      excerpt: n.excerpt,
      content: n.content,
      category: n.category,
      categoryColor: n.categoryColor,
      categoryBg: n.categoryBg,
      date: n.date,
      dateEn: n.dateEn,
      image: n.image,
      views: n.views,
      featured: n.featured,
      status: n.status,
      tags: n.tags,
      location: n.location,
    }));

    const loadNews = async () => {
      try {
        // ContentManager returns static defaults instantly, then upgrades to Sanity
        const result = await contentManager.getNews();
        if (!cancelled) {
          setNews(result.data);
          setContentSource(result.source === "sanity" ? "sanity" : "static");
        }
      } catch {
        if (!cancelled) {
          setNews(fallback);
          setContentSource("static");
        }
      } finally {
        if (!cancelled) {
          setLoading(false);
          try {
            analyticsService.generateImpactReport();
          } catch {
            /* non-critical */
          }
        }
      }
    };

    loadNews();
    return () => {
      cancelled = true;
    };
  }, []);

  // تصفية الأخبار
  const filteredNews = useMemo(() => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    return news.filter((n: any) => {
      const matchesCategory = activeCategory === "الكل" || n.category === activeCategory;
      const matchesSearch =
        n.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
        (n.excerpt && n.excerpt.toLowerCase().includes(searchQuery.toLowerCase()));
      return matchesCategory && matchesSearch;
    });
  }, [news, activeCategory, searchQuery]);

  // الأخبار المميزة
  const featuredNews = useMemo(() => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    return news.filter((n: any) => n.featured).slice(0, 3);
  }, [news]);

  if (loading) {
    return <NewsLoadingSkeleton />;
  }

  return (
    <div className="min-h-screen bg-[var(--background)]" dir="rtl">
      {/* Unified Page Header */}
      <PageHeader
        icon={Newspaper}
        badge="الأخبار والفعاليات"
        title="آخر الأخبار"
        subtitle="تابع أخبار رحماء بينهم والفعاليات القادمة، وتعرف على أحدث الإنجازات والمبادرات"
      >
        <StatsGrid
          stats={[
            { label: "خبر منشور", value: news.length, icon: BarChart3, color: "green" },
            { label: "أخبار مميزة", value: featuredNews.length, icon: TrendingUp, color: "gold" },
            { label: "فئة", value: NEWS_CATEGORIES.length - 1, icon: Tag, color: "blue" },
            {
              label: "مشاهدة",
              value: news.reduce((sum, n) => sum + (n.views || 0), 0).toLocaleString("ar-SA"),
              icon: Eye,
              color: "purple",
            },
          ]}
          columns={4}
          variant="glass"
        />
      </PageHeader>

      {/* ═══════ آية قرآنية ═══════ */}
      <div className="my-8 rounded-2xl border border-[var(--brand-gold)]/20 bg-gradient-to-l from-[var(--brand-gold)]/5 to-transparent p-6 text-center">
        <p className="font-amiri text-xl leading-loose text-[var(--foreground)] md:text-2xl" dir="rtl">
          ﴿ قُلْ هَذِهِ سَبِيلِي أَدْعُو إِلَى اللَّهِ ﴾
        </p>
        <p className="mt-3 text-sm text-[var(--muted-foreground)]">سورة يوسف، الآية ١٠٨</p>
      </div>

      {/* Category Filter */}
      <section className="py-6 bg-[var(--background)] border-b border-[var(--border)]">
        <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
          <div className="flex flex-wrap items-center justify-between gap-4">
            <div className="flex flex-wrap gap-2">
              <button
                key="all"
                onClick={() => setActiveCategory("الكل")}
                className={`px-4 py-2 rounded-full text-sm font-medium transition-all ${
                  activeCategory === "الكل"
                    ? "bg-[var(--brand-green)] text-white shadow-lg"
                    : "bg-[var(--muted)] text-[var(--muted-foreground)] hover:bg-[var(--muted)]"
                }`}
              >
                الكل
              </button>
              {NEWS_CATEGORIES.map((cat) => (
                <button
                  key={cat.id}
                  onClick={() => setActiveCategory(cat.name)}
                  className={`px-4 py-2 rounded-full text-sm font-medium transition-all`}
                  style={{
                    backgroundColor: activeCategory === cat.name ? cat.color : cat.bg,
                    color: activeCategory === cat.name ? "white" : cat.color,
                  }}
                >
                  {cat.name}
                </button>
              ))}
            </div>

            <div className="relative">
              <Search className="w-4 h-4 absolute right-3 top-1/2 -translate-y-1/2 text-[var(--muted-foreground)]" />
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="بحث في الأخبار..."
                className="w-64 pr-10 pl-4 py-2 border border-[var(--border)] rounded-full text-sm focus:outline-none focus:ring-2 focus:ring-[var(--brand-green)]/30"
              />
            </div>
          </div>
        </div>
      </section>

      {/* Featured News */}
      {featuredNews.length > 0 && (
        <section className="py-12 bg-[var(--secondary)]">
          <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
            <motion.div
              initial={{ opacity: 0, y: 30 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              className="text-center mb-10"
            >
              <span className="inline-flex items-center gap-2 text-[var(--brand-gold)] text-sm font-semibold bg-[var(--brand-gold-pale)] px-4 py-1.5 rounded-full mb-4">
                <TrendingUp className="w-4 h-4" />
                مميزة
              </span>
              <h2 className="text-2xl font-bold text-[var(--foreground)]">أبرز الأخبار</h2>
            </motion.div>

            <div className="grid md:grid-cols-3 gap-6 max-w-6xl mx-auto">
              // eslint-disable-next-line @typescript-eslint/no-explicit-any
              {featuredNews.map((n: any, i: number) => (
                <motion.article
                  key={n.id}
                  initial={{ opacity: 0, y: 20 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={{ once: true }}
                  transition={{ delay: i * 0.1 }}
                  className="group bg-[var(--card)] rounded-3xl overflow-hidden border border-[var(--border)] shadow-lg hover:shadow-2xl transition-all duration-500 hover:-translate-y-2 flex flex-col"
                >
                  {n.image && (
                    <div className="relative h-48 overflow-hidden">
                      <img
                        src={n.image}
                        alt={n.title}
                        className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105"
                        loading="lazy"
                      />
                      <div className="absolute top-3 right-3 bg-[var(--brand-gold)] text-white px-2.5 py-1 rounded-full text-xs font-bold flex items-center gap-1">
                        <TrendingUp className="w-3 h-3" />
                        مميز
                      </div>
                    </div>
                  )}
                  <div className="p-6 flex-1 flex flex-col">
                    <div className="flex items-center gap-2 mb-3">
                      <span
                        className="px-2.5 py-1 rounded-full text-xs font-bold"
                        style={{
                          background: n.categoryBg || "var(--brand-green-pale)",
                          color: n.categoryColor || "var(--brand-green)",
                        }}
                      >
                        {n.category}
                      </span>
                      <span className="text-[var(--muted-foreground)] text-xs">• {n.date}</span>
                    </div>
                    <h3 className="font-bold text-lg text-[var(--foreground)] mb-2 group-hover:text-[var(--brand-green)] transition-colors line-clamp-2">
                      {n.title}
                    </h3>
                    <p className="text-sm text-[var(--muted-foreground)] mb-4 flex-1 line-clamp-3">
                      {n.excerpt}
                    </p>
                    <button
                      onClick={() => navigate(`/news/${n.id}`)}
                      className="mt-auto flex items-center gap-1 text-sm font-semibold text-[var(--brand-green)] hover:text-[var(--brand-green-light)] transition-colors"
                    >
                      اقرأ المزيد
                      <ArrowLeft className="w-4 h-4" />
                    </button>
                  </div>
                </motion.article>
              ))}
            </div>
          </div>
        </section>
      )}

      {/* News Grid */}
      <section className="py-12 bg-[var(--background)]">
        <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
          {news.length === 0 ? (
            <div className="text-center py-16">
              <FolderOpen className="w-16 h-16 text-[var(--muted-foreground)] mx-auto mb-4 opacity-50" />
              <h3 className="text-[var(--foreground)] text-lg font-semibold mb-2">
                لا توجد أخبار حالياً
              </h3>
              <p className="text-[var(--muted-foreground)]">
                نعمل على إضافة محتوى جديد، تابعنا لاحقاً
              </p>
            </div>
          ) : filteredNews.length === 0 ? (
            <div className="text-center py-16">
              <Search className="w-16 h-16 text-[var(--muted-foreground)] mx-auto mb-4" />
              <h3 className="text-xl font-semibold text-[var(--foreground)] mb-2">
                لا توجد أخبار مطابقة
              </h3>
              <p className="text-[var(--muted-foreground)]">جرب تغيير معايير البحث أو الفئة</p>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              // eslint-disable-next-line @typescript-eslint/no-explicit-any
              {filteredNews.map((n: any) => (
                <article
                  key={n.id}
                  className="bg-[var(--card)] rounded-2xl border border-[var(--border)] overflow-hidden hover:shadow-xl transition-all duration-300 hover:-translate-y-1 flex flex-col"
                >
                  {n.image && (
                    <img
                      src={n.image}
                      alt={n.title}
                      className="w-full h-48 object-cover"
                      loading="lazy"
                    />
                  )}
                  <div className="p-6 flex-1 flex flex-col">
                    <div className="flex items-center gap-2 mb-3">
                      <span
                        className="px-2.5 py-1 rounded-full text-xs font-bold"
                        style={{
                          background: n.categoryBg || "var(--brand-green-pale)",
                          color: n.categoryColor || "var(--brand-green)",
                        }}
                      >
                        {n.category}
                      </span>
                      <span className="text-[var(--muted-foreground)] text-xs">• {n.date}</span>
                    </div>
                    <h3
                      className="font-bold text-[var(--foreground)] mb-2 line-clamp-2"
                      style={{ fontSize: "1rem" }}
                    >
                      {n.title}
                    </h3>
                    <p
                      className="text-[var(--muted-foreground)] flex-1 mb-4 line-clamp-3"
                      style={{ fontSize: "0.85rem", lineHeight: "1.7" }}
                    >
                      {n.excerpt}
                    </p>
                    <div className="flex items-center justify-between pt-3 border-t border-[var(--border)]">
                      <div className="flex items-center gap-3 text-xs text-[var(--muted-foreground)]">
                        <div className="flex items-center gap-1">
                          <Calendar className="w-3.5 h-3.5" />
                          {n.date}
                        </div>
                        <span className="w-1 h-1 bg-[var(--muted)] rounded-full" />
                        <div className="flex items-center gap-1">
                          <Eye className="w-3.5 h-3.5" />
                          {n.views || 0}
                        </div>
                      </div>
                      <button
                        onClick={() => navigate(`/news/${n.id}`)}
                        className="px-4 py-1.5 bg-[var(--brand-green)] text-white rounded-lg text-xs hover:bg-[var(--brand-green-light)] transition-colors"
                      >
                        اقرأ المزيد
                      </button>
                    </div>
                  </div>
                </article>
              ))}
            </div>
          )}
        </div>
      </section>
    </div>
  );
}

