                  </p>
                </motion.div>
              )}
            </motion.button>
          );
        })}
      </div>

      {/* مبلغ مخصص */}
      <div className="max-w-md mx-auto">
        <label className="block text-sm font-medium text-[var(--foreground)] mb-2 text-center">
