                <div className="mt-1 text-xs text-white/55">زكاة المال عند تحقق الشروط</div>
              </div>
              <div className="rounded-2xl border border-white/10 bg-white/8 p-4">
                <div className="text-2xl font-extrabold text-[var(--brand-gold)]">٨٥غ</div>
                <div className="mt-1 text-xs text-white/55">مرجع نصاب الذهب</div>
              </div>
