              >
                <Icon
                  className={`h-5 w-5 ${mode === id ? "text-[var(--brand-gold)]" : "text-[var(--brand-green)]"}`}
                />
                <span className="mt-3 block text-sm font-extrabold">{title}</span>
                <span
                  className={`mt-1 block text-[10px] leading-5 ${mode === id ? "text-white/55" : "text-[var(--muted-foreground)]"}`}
