                  suffix="ر.ي"
                  value={receivables}
                  onChange={setReceivables}
                />
                <Field
                  label="الالتزامات الحالّة"
                  suffix="ر.ي"
                  value={liabilities}
                  onChange={setLiabilities}
                />
                <Field
                  label="سعر غرام الذهب المرجعي"
                  suffix="ر.ي"
                  value={goldPrice}
                  onChange={setGoldPrice}
                />
              </>
