                  onChange={setGoldWeight}
                />
                <Field
                  label="سعر غرام الذهب المرجعي"
                  suffix="ر.ي"
                  value={goldPrice}
                  onChange={setGoldPrice}
                />
              </>
            )}
            {mode === "silver" && (
              <>
                <Field
                  label="وزن الفضة المملوك"
                  suffix="غرام"
                  value={silverWeight}
                  onChange={setSilverWeight}
                />
                <Field
                  label="سعر غرام الفضة المرجعي"
                  suffix="ر.ي"
                  value={silverPrice}
                  onChange={setSilverPrice}
                />
              </>
            )}
            {mode === "fitr" && (
              <>
                <Field
                  label="عدد الأشخاص"
                  suffix="شخص"
                  value={fitrPeople}
                  onChange={setFitrPeople}
                  min={1}
                />
                <Field
                  label="قيمة زكاة الفطر للشخص"
                  suffix="ر.ي"
                  value={fitrValue}
                  onChange={setFitrValue}
                />
              </>
            )}
          </div>

          {mode !== "fitr" && (
            <label className="mt-6 flex cursor-pointer items-center gap-3 rounded-2xl border border-[var(--brand-green)]/10 bg-[var(--brand-green-pale)] p-4 text-sm font-bold text-[var(--brand-green)]">
              <input
                type="checkbox"
                checked={hasHawl}
                onChange={(event) => setHasHawl(event.target.checked)}
                className="h-5 w-5 accent-[var(--brand-green)]"
              />{" "}
              حال على المال الحول الهجري الكامل{" "}
              <span className="mr-auto text-xs font-normal text-[var(--muted-foreground)]">
                شرط إرشادي للحساب
              </span>
            </label>
          )}

          <div className="mt-8 flex flex-col gap-3 sm:flex-row">
            <button
              type="button"
              onClick={calculate}
              className="inline-flex min-h-12 flex-1 items-center justify-center gap-2 rounded-2xl bg-[var(--brand-green)] px-6 text-sm font-extrabold text-white shadow-lg transition hover:bg-[var(--brand-green-light)]"
            >
              <Calculator className="h-4 w-4" /> احسب النتيجة
            </button>
            <button
              type="button"
              onClick={reset}
              className="inline-flex min-h-12 items-center justify-center gap-2 rounded-2xl border border-[var(--brand-green)]/15 px-5 text-sm font-bold text-[var(--brand-green)] transition hover:bg-[var(--brand-green-pale)]"
            >
              <RotateCcw className="h-4 w-4" /> إعادة ضبط
            </button>
          </div>

          {result !== null && (
            <motion.div
              initial={{ opacity: 0, y: 12 }}
              animate={{ opacity: 1, y: 0 }}
              className="mt-8 rounded-[24px] border border-[var(--brand-gold)]/35 bg-[var(--brand-gold-pale)] p-6"
            >
              <div className="flex flex-col justify-between gap-5 sm:flex-row sm:items-center">
                <div>
                  <div className="flex items-center gap-2 text-sm font-bold text-[var(--brand-gold-dark)]">
                    <CheckCircle2 className="h-5 w-5" /> النتيجة الإرشادية
                  </div>
                  <div className="mt-3 text-4xl font-extrabold text-[var(--brand-green)]">
                    {formatNumber(result, 2)} <span className="text-base">ر.ي</span>
                  </div>
                  <p className="mt-2 text-xs leading-6 text-[var(--muted-foreground)]">
                    {mode === "fitr"
                      ? `على أساس ${formatNumber(fitrPeople)} أشخاص × ${formatNumber(fitrValue)} ر.ي — مجموع واجب الفطر`
                      : calculation.eligible
                        ? `نسبة ٢٫٥٪ من أصل ${formatNumber(calculation.base, 2)} ${calculation.unit} بعد خصم الالتزامات`
                        : "لم يتحقق النصاب أو شرط الحول وفق المدخلات الحالية — يُنصح بمراجعة أهل العلم."}
                  </p>
                </div>
                <button
                  type="button"
                  onClick={saveCalculation}
                  className="inline-flex min-h-11 items-center justify-center gap-2 rounded-xl border border-[var(--brand-green)]/15 bg-white px-4 text-xs font-bold text-[var(--brand-green)]"
                >
                  {saved ? (
                    <CheckCircle2 className="h-4 w-4 text-[var(--success)]" />
                  ) : (
                    <History className="h-4 w-4" />
                  )}{" "}
                  {saved ? "حُفظت العملية" : "حفظ في السجل"}
                </button>
              </div>
            </motion.div>
          )}
        </section>

        <aside className="space-y-4">
          <div className="rounded-[24px] bg-[var(--brand-green)] p-6 text-white">
            <ShieldCheck className="h-7 w-7 text-[var(--brand-gold)]" />
            <h2 className="mt-5 text-lg font-extrabold">منهج الحساب الشرعي</h2>
            <p className="mt-3 text-xs leading-7 text-white/65">
              تعتمد الأداة على أصول الفقه المعتمدة في حساب الزكاة: يُعرض النصاب بوضوح، وتُخصَّم
              الالتزامات الحالّة من إجمالي المال قبل احتساب نسبته. لا تُخفِي الأداة أي فرضية مؤثرة
              في النتيجة النهائية.
            </p>
            <div className="mt-5 space-y-3 border-t border-white/10 pt-5 text-xs text-white/70">
              <div className="flex justify-between">
                <span>معدل زكاة المال</span>
                <strong className="text-[var(--brand-gold)]">٢٫٥٪</strong>
              </div>
              <div className="flex justify-between">
                <span>نصاب الذهب</span>
                <strong className="text-[var(--brand-gold)]">٨٥ غ</strong>
              </div>
              <div className="flex justify-between">
                <span>نصاب الفضة</span>
                <strong className="text-[var(--brand-gold)]">٥٩٥ غ</strong>
              </div>
            </div>
          </div>
          <div className="rounded-[24px] border border-[var(--brand-green)]/10 bg-white p-6">
            <div className="flex items-center gap-3">
              <BookOpen className="h-5 w-5 text-[var(--brand-gold-dark)]" />
              <h2 className="text-sm font-extrabold text-[var(--brand-green)]">تنبيه شرعي مهم</h2>
            </div>
            <p className="mt-4 text-xs leading-7 text-[var(--muted-foreground)]">
              هذه أداة إرشادية لتسهيل الحساب ولا تُغني عن الفتوى. في زكاة عروض التجارة، الأسهم،
              الصناديق الاستثمارية، أو اختلاف الحول والنصاب، يُنصح بمراجعة عالم أهل العلم أو جهة
              شرعية موثوقة قبل إخراج الزكاة.
            </p>
            <div className="mt-5 flex items-start gap-2 rounded-xl bg-[var(--brand-gold-pale)] p-3 text-[11px] leading-5 text-[var(--brand-gold-dark)]">
              <AlertCircle className="mt-0.5 h-4 w-4 shrink-0" /> سعر الذهب وقيمة زكاة الفطر
              يختلفان من دولة لأخرى ويزولان محليًا — يُنصح بتحديثهما قبل الحساب.
            </div>
          </div>
          <button
            type="button"
            onClick={() => navigate("/donate")}
            className="flex w-full items-center justify-center gap-2 rounded-2xl border border-[var(--brand-green)]/15 bg-[var(--brand-green-pale)] text-[var(--brand-green)] transition hover:bg-[var(--brand-green-pale)]"
          >
            <Sparkles className="h-4 w-4 text-[var(--brand-gold-dark)]" /> أخرج زكاتك عبر رحماء
            بينهم <ArrowLeft className="h-4 w-4" />
          </button>
        </aside>
      </main>
    </div>
  );
}

function Field({
  label,
  suffix,
  value,
  onChange,
  min = 0,
}: {
  label: string;
  suffix: string;
  value: number;
  onChange: (value: number) => void;
  min?: number;
}) {
  const fieldId = `field-${label.replace(/\s+/g, "-")}`;
  return (
    <label htmlFor={fieldId} className="block">
      <span className="mb-2 block text-xs font-bold text-[var(--brand-green)]">{label}</span>
      <div className="relative">
        <input
          id={fieldId}
          type="number"
          min={min}
          value={value || ""}
          onChange={(event) => onChange(Math.max(min, Number(event.target.value) || 0))}
          className="min-h-12 w-full rounded-2xl border border-[var(--brand-green)]/12 bg-[var(--brand-green-pale)] px-4 pl-16 text-sm font-bold text-[var(--brand-ink)] outline-none transition focus:border-[var(--brand-green)] focus:ring-4 focus:ring-[var(--brand-green)]/10"
          placeholder="0"
        />
        <span className="absolute left-4 top-1/2 -translate-y-1/2 text-xs text-[var(--muted-foreground)]">
          {suffix}
        </span>
      </div>
    </label>
  );
}

